// Command specgen generates code from SSOT specs and verifies generated files are current.
//
//	go run ./cmd/specgen          # write generated files
//	go run ./cmd/specgen -check   # exit 1 if any generated file is stale (L1 gate)
//
// Spec → outputs:
//
//	specs/failures.json → helper/internal/engine/failures_gen.go, panel/core/src/failures.gen.ts
//	specs/principles.json + loop/policy.json → AGENTS.md (CLAUDE.md가 import)
//
// 각 산출물 머리에 의미 해시(semantic hash)를 넣는다: 설명 필드(meaning/note/$schema)를 뺀 정규형 JSON의
// sha256. 설명만 바꾸면 해시가 같고, 정책·메시지·종류를 바꾸면 해시가 바뀐다.
package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"birdcage/tools/internal/loopkit"
)

type policy struct {
	ID      string `json:"id"`
	GoName  string `json:"goName"`
	Meaning string `json:"meaning"`
}

type kind struct {
	ID      string `json:"id"`
	GoName  string `json:"goName"`
	Policy  string `json:"policy"`
	Message string `json:"message"`
	Note    string `json:"note,omitempty"`
}

type failureSpec struct {
	Version  int      `json:"version"`
	Policies []policy `json:"policies"`
	Kinds    []kind   `json:"kinds"`
}

// Semantic returns the canonical meaning-bearing form (descriptions excluded).
func (s failureSpec) Semantic() []byte {
	type sp struct{ ID, GoName string }
	type sk struct{ ID, GoName, Policy, Message string }
	c := struct {
		Version  int
		Policies []sp
		Kinds    []sk
	}{Version: s.Version}
	for _, p := range s.Policies {
		c.Policies = append(c.Policies, sp{p.ID, p.GoName})
	}
	for _, k := range s.Kinds {
		c.Kinds = append(c.Kinds, sk{k.ID, k.GoName, k.Policy, k.Message})
	}
	b, _ := json.Marshal(c)
	return b
}

// Hash is the semantic hash of the spec.
func (s failureSpec) Hash() string {
	sum := sha256.Sum256(s.Semantic())
	return "sha256:" + hex.EncodeToString(sum[:])
}

func (s failureSpec) validate() error {
	pol := map[string]bool{}
	names := map[string]bool{}
	for _, p := range s.Policies {
		if pol[p.ID] || names["P"+p.GoName] {
			return fmt.Errorf("duplicate policy %s", p.ID)
		}
		pol[p.ID], names["P"+p.GoName] = true, true
	}
	ids := map[string]bool{}
	for _, k := range s.Kinds {
		if ids[k.ID] || names["K"+k.GoName] {
			return fmt.Errorf("duplicate kind %s/%s", k.ID, k.GoName)
		}
		ids[k.ID], names["K"+k.GoName] = true, true
		if !pol[k.Policy] {
			return fmt.Errorf("kind %s: unknown policy %q", k.ID, k.Policy)
		}
	}
	return nil
}

type output struct {
	rel  string
	data []byte
}

func generate(root string) ([]output, error) {
	v := loopkit.NewValidator(root)
	if err := v.ValidateFile("specs/failures.schema.json", "specs/failures.json"); err != nil {
		return nil, err
	}
	var s failureSpec
	if err := loopkit.ReadJSON(root, "specs/failures.json", &s); err != nil {
		return nil, err
	}
	if err := s.validate(); err != nil {
		return nil, fmt.Errorf("specs/failures.json: %w", err)
	}
	goSrc, err := goFailures(s)
	if err != nil {
		return nil, err
	}
	ps, pol, hash, err := loadAgentsInputs(root)
	if err != nil {
		return nil, err
	}
	return []output{
		{"helper/internal/engine/failures_gen.go", goSrc},
		{"panel/core/src/failures.gen.ts", tsFailures(s)},
		{"AGENTS.md", agentsMD(ps, pol, hash)},
	}, nil
}

const header = "Code generated by specgen from specs/failures.json; DO NOT EDIT."

func goFailures(s failureSpec) ([]byte, error) {
	var b bytes.Buffer
	pName := map[string]string{}
	for _, p := range s.Policies {
		pName[p.ID] = "Policy" + p.GoName
	}
	fmt.Fprintf(&b, "// %s\n// semantic-hash: %s\n\npackage engine\n\n", header, s.Hash())
	b.WriteString("// Kind classifies a failure.\ntype Kind string\n\n")
	b.WriteString("// Policy is what the job runner should do after a failure.\ntype Policy string\n\n")
	fmt.Fprintf(&b, "// FailureSpecHash identifies the meaning of specs/failures.json.\nconst FailureSpecHash = %q\n\n", s.Hash())
	b.WriteString("const (\n")
	for _, p := range s.Policies {
		fmt.Fprintf(&b, "\t%s Policy = %q // %s\n", pName[p.ID], p.ID, p.Meaning)
	}
	b.WriteString(")\n\nconst (\n")
	for _, k := range s.Kinds {
		fmt.Fprintf(&b, "\tKind%s Kind = %q\n", k.GoName, k.ID)
	}
	b.WriteString(")\n\n// AllKinds lists every failure kind in spec order.\nvar AllKinds = []Kind{\n")
	for _, k := range s.Kinds {
		fmt.Fprintf(&b, "\tKind%s,\n", k.GoName)
	}
	b.WriteString("}\n\nvar kindPolicy = map[Kind]Policy{\n")
	for _, k := range s.Kinds {
		fmt.Fprintf(&b, "\tKind%s: %s,\n", k.GoName, pName[k.Policy])
	}
	b.WriteString("}\n\nvar kindMessage = map[Kind]string{\n")
	for _, k := range s.Kinds {
		fmt.Fprintf(&b, "\tKind%s: %s,\n", k.GoName, strconv.Quote(k.Message))
	}
	b.WriteString("}\n\n// PolicyFor maps a failure kind to the runner policy. Unknown kinds stop.\n")
	b.WriteString("func PolicyFor(k Kind) Policy {\n\tif p, ok := kindPolicy[k]; ok {\n\t\treturn p\n\t}\n\treturn PolicyStop\n}\n\n")
	b.WriteString("// MessageFor returns the user-facing (Korean) message for a kind.\nfunc MessageFor(k Kind) string { return kindMessage[k] }\n")
	return format.Source(b.Bytes())
}

func tsFailures(s failureSpec) []byte {
	var b bytes.Buffer
	q := func(x string) string { j, _ := json.Marshal(x); return string(j) }
	fmt.Fprintf(&b, "// %s\n// semantic-hash: %s\n\n", header, s.Hash())
	fmt.Fprintf(&b, "export const FAILURE_SPEC_HASH = %s;\n\n", q(s.Hash()))
	b.WriteString("export const FAILURE_POLICIES = [\n")
	for _, p := range s.Policies {
		fmt.Fprintf(&b, "  %s, // %s\n", q(p.ID), p.Meaning)
	}
	b.WriteString("] as const;\nexport type FailurePolicy = (typeof FAILURE_POLICIES)[number];\n\n")
	b.WriteString("export const FAILURE_KINDS = [\n")
	for _, k := range s.Kinds {
		fmt.Fprintf(&b, "  %s,\n", q(k.ID))
	}
	b.WriteString("] as const;\nexport type FailureKind = (typeof FAILURE_KINDS)[number];\n\n")
	b.WriteString("export const FAILURE_POLICY: Record<FailureKind, FailurePolicy> = {\n")
	for _, k := range s.Kinds {
		fmt.Fprintf(&b, "  %s: %s,\n", k.ID, q(k.Policy))
	}
	b.WriteString("};\n\nexport const FAILURE_MESSAGE: Record<FailureKind, string> = {\n")
	for _, k := range s.Kinds {
		fmt.Fprintf(&b, "  %s: %s,\n", k.ID, q(k.Message))
	}
	b.WriteString("};\n")
	return b.Bytes()
}

func main() {
	check := flag.Bool("check", false, "verify generated files are up to date (exit 1 if stale)")
	flag.Parse()
	root, err := loopkit.Root(".")
	if err != nil {
		fail(err)
	}
	outs, err := generate(root)
	if err != nil {
		fail(err)
	}
	stale := 0
	for _, o := range outs {
		p := filepath.Join(root, filepath.FromSlash(o.rel))
		cur, _ := os.ReadFile(p)
		if bytes.Equal(cur, o.data) {
			if *check {
				fmt.Printf("ok     %s\n", o.rel)
			}
			continue
		}
		if *check {
			fmt.Printf("STALE  %s (run: make gen)\n", o.rel)
			stale++
			continue
		}
		if err := os.WriteFile(p, o.data, 0o644); err != nil {
			fail(err)
		}
		fmt.Printf("wrote  %s\n", o.rel)
	}
	if stale > 0 {
		os.Exit(1)
	}
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, "specgen:", strings.TrimSpace(err.Error()))
	os.Exit(1)
}
